//! Compatibility evidence uses files generated by the real student service/exporter code.
use serde_json::Value;
use std::{fs, path::Path};

#[test]
fn real_student_v1_and_v2_snapshots_import_with_full_writing_and_slot_values() {
    for version in [1, 2] {
        let root = std::env::temp_dir().join(format!(
            "snapshot-compat-v{version}-{}",
            uuid::Uuid::new_v4()
        ));
        let fixture = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join(format!("../fixtures/analytics/student-v{version}"));
        let provenance: Value =
            serde_json::from_slice(&fs::read(fixture.join("provenance.json")).unwrap()).unwrap();
        assert_eq!(provenance["dbSchemaVersion"], version);
        let target = root.join("nas/snapshots/fixture-terminal");
        fs::create_dir_all(&target).unwrap();
        for entry in fs::read_dir(&fixture).unwrap() {
            let e = entry.unwrap();
            if e.file_name() != "provenance.json" {
                fs::copy(e.path(), target.join(e.file_name())).unwrap();
            }
        }
        let mut conn = super::open_analytics(&root).unwrap();
        let report =
            super::import::import_submission_snapshots(&mut conn, &root, &root.join("nas"))
                .unwrap();
        assert_eq!(report.attempts_imported, 1, "{report:?}");
        assert_eq!(report.failed, 0, "{report:?}");
        let content: String = conn
            .query_row("SELECT content FROM writings", [], |r| r.get(0))
            .unwrap();
        assert!(content.contains("中文🙂 retained"));
        assert_eq!(
            conn.query_row(
                "SELECT COUNT(*) FROM answers WHERE response_slot_id IS NOT NULL",
                [],
                |r| r.get::<_, i64>(0)
            )
            .unwrap(),
            3
        );
        drop(conn);
        let _ = fs::remove_dir_all(root);
    }
}
